private TAMRebateDeal getCurrentRebateDeal()
{
    TAMRebateTable rebateTable;
    TAMRebateDeal  rebateDeal;

    select firstonly RebateFromDate, RebateToDate from rebateDeal
        exists join rebateTable
            where rebateTable.RebateId == this.RebateId
               && rebateTable.RebateDeal == rebateDeal.RecId;

    return rebateDeal;
}

public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        TAMRebateDeal rebateDeal = this.getCurrentRebateDeal();
        if (rebateDeal.RebateReconciliation == TAMRebateReconciliation::Deal && (this.orig().RebateFromDate != this.RebateFromDate || this.orig().RebateToDate != this.RebateToDate))
        {
            if (rebateDeal.RebateFromDate > this.RebateFromDate || rebateDeal.RebateToDate < this.RebateToDate)
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:RebateDateRangeOnLineShouldUnderHeaderRange", rebateDeal.RebateFromDate, rebateDeal.RebateToDate));
            }
        }
    }

    return ret;
}

edit TAMRebatePeriodCodeGUP editPeriodCodeEnumGUP(boolean _set, TAMRebatePeriodCodeGUP _rebatePeriodCode)
{
    if (_set)
    {
        this.RebatePeriodCode = TAMRebateDate::periodCodeGUPToPeriodCode(_rebatePeriodCode);
    }
    return TAMRebateDate::periodCodeToPeriodCodeGUP(this.RebatePeriodCode);
}

edit TAMRebatePeriodCodeGUP editClaimByEnumGUP(boolean _set, TAMRebatePeriodCodeGUP _rebateClaimBy)
{
    if (_set)
    {
        this.RebateClaimBy = TAMRebateDate::periodCodeGUPToPeriodCode(_rebateClaimBy);
    }
    return TAMRebateDate::periodCodeToPeriodCodeGUP(this.RebateClaimBy);
}

public static TAMRebatePeriodCodeGUP periodCodeToPeriodCodeGUP(TAMRebatePeriodCode _periodCode)
{
    switch (_periodCode)
    {
        case TAMRebatePeriodCode::Month:
            return TAMRebatePeriodCodeGUP::Month;
        case TAMRebatePeriodCode::Year:
            return TAMRebatePeriodCodeGUP::Year;
        case TAMRebatePeriodCode::FinancialYear:
            return TAMRebatePeriodCodeGUP::FinancialYear;
    }
    return TAMRebatePeriodCodeGUP::Month;
}

public static TAMRebatePeriodCode periodCodeGUPToPeriodCode(TAMRebatePeriodCodeGUP _periodCodeGUP)
{
    switch (_periodCodeGUP)
    {
        case TAMRebatePeriodCodeGUP::Month:
            return TAMRebatePeriodCode::Month;
        case TAMRebatePeriodCodeGUP::Year:
            return TAMRebatePeriodCode::Year;
        case TAMRebatePeriodCodeGUP::FinancialYear:
            return TAMRebatePeriodCode::FinancialYear;
    }
    return TAMRebatePeriodCode::Month;
}
